-- Family stats (#56, part 1): the counts behind "This month" on the Family tab.
begin;
select plan(14);

create function pg_temp.as_user(uid uuid) returns void language sql as $$
  select set_config('request.jwt.claims', json_build_object('sub', uid, 'role', 'authenticated')::text, true),
         set_config('role', 'authenticated', true);
$$;

-- October 1 to 20, 2026, for the Andersons.
create function pg_temp.stat(key text) returns int language sql as $$
  select (public.family_stats('00000000-0000-0000-0000-0000000000a0', '2026-10-01', '2026-10-20') ->> key)::int;
$$;

