-- Bob, a member, sees the household's stats.
select pg_temp.as_user('b0000000-0000-0000-0000-00000000000b');
select is(pg_temp.stat('dinners'), 9,
  'dinners: approved nights in the range with a dish or quick pick (not the draft week, the empty night, or after)');
select is(pg_temp.stat('dishes'), 4, 'dishes: those with a dish');
select is(pg_temp.stat('ideas'), 1, 'ideas: one night, from members only, with a dish, in an approved week in the range');
select is(pg_temp.stat('cooked_by_others'), 2,
  'cooked by others: Bob and Dan this month, not Alice, the usual cook (June is too long ago; takeout and drafts don''t count)');
select is(pg_temp.stat('at_table'), 7, 'at the table: dishes, takeout, leftovers, and the freezer, not eating out or fending');
select is(pg_temp.stat('new_dishes'), 1, 'new dishes: pho, once; not pot roast from August or ramen from a draft week');
select is(pg_temp.stat('weeks_planned'), 3, 'weeks planned: approved weeks touching the range, even partly');
select is((public.family_stats('00000000-0000-0000-0000-0000000000a0', '2026-12-01', '2026-12-02'))::jsonb,
  '{"dinners": 0, "dishes": 0, "ideas": 0, "cooked_by_others": 0, "at_table": 0, "new_dishes": 0, "weeks_planned": 0}'::jsonb,
  'a month with nothing yet is all zeros');

-- Two more for Bob in August ties him with Alice: both are usual, and only Dan cooked "for" them.
