   '00000000-0000-0000-0000-0000000000a2');
select pg_temp.as_user('b0000000-0000-0000-0000-00000000000b');
select is(pg_temp.stat('cooked_by_others'), 1, 'a tie makes both usual cooks');

-- Everyone in the household sees the same card.
select pg_temp.as_user('a0000000-0000-0000-0000-00000000000a');
select is(pg_temp.stat('dinners'), 9, 'the owner sees the same counts');

-- Another household learns nothing.
select pg_temp.as_user('c0000000-0000-0000-0000-00000000000c');
select is((public.family_stats('00000000-0000-0000-0000-0000000000a0', '2026-10-01', '2026-10-20'))::jsonb,
  '{"dinners": 0, "dishes": 0, "ideas": 0, "cooked_by_others": 0, "at_table": 0, "new_dishes": 0, "weeks_planned": 0}'::jsonb,
  'another household''s member gets zeros');

reset role;
select ok(not has_function_privilege('anon', 'public.family_stats(uuid, date, date)', 'execute'), 'not for anon');
select ok(not has_function_privilege('public', 'public.family_stats(uuid, date, date)', 'execute'), 'not for public');
select ok(has_function_privilege('authenticated', 'public.family_stats(uuid, date, date)', 'execute'),
  'for signed-in people');

select * from finish();
rollback;
